// State-of-the-art C++ float-to-string / float-to-decimal baselines over
// the shared bench corpora (benches/corpora.cpp, generated by gen_corpora.py,
// bit-identical to what the Lean and Python harnesses iterate).
//
// Usage: ./bench_sota <impl> <corpus> [--checksum]
//   impl (Float -> String, fresh std::string per call is the "_str" variant,
//         matching the Lean harness which returns a heap String every call):
//     chars          std::to_chars shortest (libstdc++: Ryu), reused buffer
//     chars_str      std::to_chars + std::string
//     ryu            Ryu d2s_buffered_n (scientific "1.2345E6"), reused buffer
//     ryu_str        Ryu + std::string
//     dragonbox      jkj::dragonbox::to_chars_n (scientific "1.2345E6")
//     dragonbox_str  Dragonbox + std::string
//     leanfmt        Dragonbox to_decimal + hand-rolled emit of EXACTLY the
//                    Lean text form "[-]<sig>e<exp>" (sig without trailing
//                    zeros), reused buffer
//     leanfmt_str    same + std::string
//     snprintf       libc "%.17g" (not shortest; for orientation only)
//   impl (Float -> Decimal, no string; the analogue of Printer.toDecimal):
//     ryu_dec        Ryu d2d (+ the small-int trailing-zero strip d2s does)
//     dragonbox_dec  jkj::dragonbox::to_decimal (default: trailing zeros removed)
//
// Build: benches/bench_sota.sh   (clones/uses Ryu and Dragonbox sources)
#include "corpora.h"
#include <algorithm>
#include <bit>
#include <charconv>
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <string>
#include <vector>

#include "ryu/ryu.h"
#include "dragonbox/dragonbox_to_chars.h"

extern "C" {
// From the patched Ryu copy built by bench_sota.sh: everything
// d2s_buffered_n does except the final to_chars. Returns 1 for negative.
int ryu_d2dec(double f, uint64_t *mant, int32_t *exp);
}

using namespace std::chrono;

static inline void clobber(const void *p) {
    __asm__ volatile("" : : "g"(p) : "memory");
}

static const char DIGITS2[] =
    "0001020304050607080910111213141516171819"
    "2021222324252627282930313233343536373839"
    "4041424344454647484950515253545556575859"
    "6061626364656667686970717273747576777879"
    "8081828384858687888990919293949596979899";

// Lean's canonical text form: "[-]<sig>e<exp>", or "0" / "-0".
static inline size_t lean_fmt(bool neg, uint64_t sig, int exp, char *buf) {
    char *p = buf;
    if (neg) *p++ = '-';
    if (sig == 0) { *p++ = '0'; return (size_t)(p - buf); }
    char tmp[24];
    char *t = tmp + sizeof tmp;
    while (sig >= 100) {
        uint64_t q = sig / 100;
        unsigned r = (unsigned)(sig - q * 100);
        t -= 2; memcpy(t, DIGITS2 + 2 * r, 2);
        sig = q;
    }
    if (sig >= 10) { t -= 2; memcpy(t, DIGITS2 + 2 * sig, 2); }
    else *--t = (char)('0' + sig);
    size_t n = (size_t)(tmp + sizeof tmp - t);
    memcpy(p, t, n); p += n;
    *p++ = 'e';
    if (exp < 0) { *p++ = '-'; exp = -exp; }
    if (exp >= 100) {
        *p++ = (char)('0' + exp / 100);
        memcpy(p, DIGITS2 + 2 * (exp % 100), 2); p += 2;
    } else if (exp >= 10) {
        memcpy(p, DIGITS2 + 2 * exp, 2); p += 2;
    } else *p++ = (char)('0' + exp);
    return (size_t)(p - buf);
}

// Dragonbox to_decimal + Lean format. Zero is special-cased exactly as the
// Lean printer does (m = 0 -> "0"/"-0"); inputs are finite (corpus invariant).
static inline size_t leanfmt_convert(double f, char *buf) {
    uint64_t bits = std::bit_cast<uint64_t>(f);
    bool neg = (bits >> 63) != 0;
    if ((bits & 0x7FFFFFFFFFFFFFFFull) == 0) return lean_fmt(neg, 0, 0, buf);
    auto d = jkj::dragonbox::to_decimal(f, jkj::dragonbox::policy::sign::ignore);
    return lean_fmt(neg, d.significand, d.exponent, buf);
}

static uint64_t corpus_checksum(const std::vector<double> &xs) {
    uint64_t s = 0;
    for (double f : xs) s += std::bit_cast<uint64_t>(f);
    return s;
}

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "usage: %s <impl> <adversarial|nice|uniform> [--checksum]\n", argv[0]);
        return 1;
    }
    enum Mode { CHARS, CHARS_STR, RYU, RYU_STR, DBOX, DBOX_STR, LEANFMT, LEANFMT_STR,
                SNPRINTF, RYU_DEC, DBOX_DEC };
    const char *name = argv[1];
    Mode mode;
    if      (!strcmp(name, "chars"))         mode = CHARS;
    else if (!strcmp(name, "chars_str"))     mode = CHARS_STR;
    else if (!strcmp(name, "ryu"))           mode = RYU;
    else if (!strcmp(name, "ryu_str"))       mode = RYU_STR;
    else if (!strcmp(name, "dragonbox"))     mode = DBOX;
    else if (!strcmp(name, "dragonbox_str")) mode = DBOX_STR;
    else if (!strcmp(name, "leanfmt"))       mode = LEANFMT;
    else if (!strcmp(name, "leanfmt_str"))   mode = LEANFMT_STR;
    else if (!strcmp(name, "snprintf"))      mode = SNPRINTF;
    else if (!strcmp(name, "ryu_dec"))       mode = RYU_DEC;
    else if (!strcmp(name, "dragonbox_dec")) mode = DBOX_DEC;
    else { fprintf(stderr, "unknown impl %s\n", name); return 1; }

    const std::vector<double> *xs;
    const char *label = argv[2];
    if (strcmp(label, "nice") == 0) xs = &benches_corpora::nice;
    else if (strcmp(label, "uniform") == 0) xs = &benches_corpora::uniform;
    else xs = &benches_corpora::adversarial;

    if (argc >= 4 && strcmp(argv[3], "--checksum") == 0) {
        printf("%s: n=%zu sum_bits=%llu\n", label, xs->size(),
               (unsigned long long)corpus_checksum(*xs));
        return 0;
    }
    if (argc >= 4 && strcmp(argv[3], "--dump") == 0) {
        char buf[64];
        for (double f : *xs) {
            size_t n = leanfmt_convert(f, buf);
            printf("%.*s\n", (int)n, buf);
        }
        return 0;
    }

    const int N = 1000;
    const int M = 5;
    char buf[64];

    auto convert = [&](double f) -> size_t {
        switch (mode) {
        case CHARS: {
            auto [p, ec] = std::to_chars(buf, buf + sizeof(buf), f);
            clobber(buf);
            return (size_t)(p - buf);
        }
        case CHARS_STR: {
            auto [p, ec] = std::to_chars(buf, buf + sizeof(buf), f);
            std::string s(buf, (size_t)(p - buf));
            clobber(s.data());
            return s.size();
        }
        case RYU: {
            int n = d2s_buffered_n(f, buf);
            clobber(buf);
            return (size_t)n;
        }
        case RYU_STR: {
            int n = d2s_buffered_n(f, buf);
            std::string s(buf, (size_t)n);
            clobber(s.data());
            return s.size();
        }
        case DBOX: {
            char *p = jkj::dragonbox::to_chars_n(f, buf);
            clobber(buf);
            return (size_t)(p - buf);
        }
        case DBOX_STR: {
            char *p = jkj::dragonbox::to_chars_n(f, buf);
            std::string s(buf, (size_t)(p - buf));
            clobber(s.data());
            return s.size();
        }
        case LEANFMT: {
            size_t n = leanfmt_convert(f, buf);
            clobber(buf);
            return n;
        }
        case LEANFMT_STR: {
            size_t n = leanfmt_convert(f, buf);
            std::string s(buf, n);
            clobber(s.data());
            return s.size();
        }
        case SNPRINTF: {
            int len = snprintf(buf, sizeof(buf), "%.17g", f);
            clobber(buf);
            return (size_t)len;
        }
        case RYU_DEC: {
            uint64_t m; int32_t e;
            int neg = ryu_d2dec(f, &m, &e);
            clobber(&m); clobber(&e);
            return (size_t)(m ^ (uint64_t)(uint32_t)e ^ (uint64_t)neg);
        }
        case DBOX_DEC: {
            uint64_t bits = std::bit_cast<uint64_t>(f);
            if ((bits & 0x7FFFFFFFFFFFFFFFull) == 0) return 0;
            auto d = jkj::dragonbox::to_decimal(f);
            clobber(&d);
            return (size_t)(d.significand ^ (uint64_t)(uint32_t)d.exponent);
        }
        }
        return 0;
    };

    for (int j = 0; j < 50; j++)
        for (double f : *xs) convert(f);

    long long times[M];
    for (int run = 0; run < M; run++) {
        auto t0 = steady_clock::now();
        size_t sink = 0;
        for (int j = 0; j < N; j++)
            for (double f : *xs) sink ^= convert(f);
        auto t1 = steady_clock::now();
        long long ns = duration_cast<nanoseconds>(t1 - t0).count();
        // Tenths of a ns: the fast C++ paths are 20-50 ns, integer ns loses precision.
        times[run] = ns * 10 / (long long)N / (long long)xs->size();
        if (sink == 12345) printf("");
    }
    std::sort(times, times + M);
    printf("%s/%s: median = %lld.%lld ns/call (runs:", name, label,
           times[M / 2] / 10, times[M / 2] % 10);
    for (int i = 0; i < M; i++) printf(" %lld.%lld", times[i] / 10, times[i] % 10);
    printf(")\n");
    return 0;
}
